using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API using constructor-injected HttpClient.
/// The SDK creates a new instance per invocation, resolving DI services via the constructor.
/// </summary>
[McpServerToolType]
public class WeatherApiTools(HttpClient httpClient, ILogger<WeatherApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("Get the current weather for a city. Returns temperature, humidity, and conditions.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'London' or 'New York'")] string city,
        [Description("Units: 'metric' (Celsius) or 'imperial' (Fahrenheit). Defaults to metric.")] string units = "metric",
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching weather for {City} in {Units}", city, units);

        var response = await httpClient.GetAsync(
            $"/v1/weather?city={Uri.EscapeDataString(city)}&units={Uri.EscapeDataString(units)}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        // Re-serialize with indentation for LLM readability
        var doc = JsonSerializer.Deserialize<JsonElement>(json);
        return JsonSerializer.Serialize(doc, JsonOptions);
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name, e.g. 'Tokyo'")] string city,
        [Description("Number of days to forecast (1-7). Defaults to 3.")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 7);
        logger.LogInformation("Fetching {Days}-day forecast for {City}", days, city);

        var response = await httpClient.GetAsync(
            $"/v1/forecast?city={Uri.EscapeDataString(city)}&days={days}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        var doc = JsonSerializer.Deserialize<JsonElement>(json);
        return JsonSerializer.Serialize(doc, JsonOptions);
    }
}

